"""Write docs/scoring/HUMAN_REVIEW.md from the review files, so the conclusions live only in the JSON. No API calls.

Reads docs/scoring/scores_<label>.json (rule value), claude_review_<label>.json and human_review_<label>.json.
The evidence locations below were written when the review list was prepared (2026-11-15).

    python tools/build_human_review.py
"""
from __future__ import annotations

import json
from pathlib import Path

REPO = Path(__file__).resolve().parents[1]
OUT = REPO / 'docs/scoring'
LABELS = {'20261105': 'by the author on their own machine', '20261115': "by Claude Code with the author's authorisation (`run.sh live`)"}
WHERE = {  # (review id, evidence file -> location, what to look at)
    ('20261105', 'S1:Q06/mix'): ('05-1', '`E1/full_Q06_mix.json` → `result.llm_response.content`', 'search “No specific claim number”: the answer compares the patents but gives no claim number for US7991757B2, whose facts come from the graph without a source'),
    ('20261105', 'S3:supplement/Q11/mix'): ('05-2', '`E1/supplement_budget_Q11_supplementary_mix.json` → `result.llm_response.content` (1631 characters)', 'read in full; it opens with a refusal (“I do not have enough information”); check that the registration capability is not attributed to another patent'),
    ('20261105', 'S5:B1'): ('05-3', '`E2/ablation_B_r1.json` → `response.content`, from character 187', 'search “referencing US7991757B2”: an affirmative attribution, with no sentence denying it'),
    ('20261105', 'S5:B3'): ('05-4', '`E2/ablation_B_r3.json` → `response.content`, from character 187', 'as 05-3'),
    ('20261105', 'S9:F01_A_r3'): ('05-5', '`E3/F01_A_r3/merged_graph.json` → `edges`', 'edges mentioning the ontology are 12 and 35–41 (new medical case, multidimensional representation, UMLS, parts of the ontology); none links existing cases and experts with the ontology. One truncated extraction (call 68)'),
    ('20261105', 'S13:F01_B_r2/naive'): ('05-6', '`E3/F01_B_r2/natural_naive.json` → `result.llm_response.content`', 'search “(Claims 4, 5, 8)”: listed as a technical chain, not as a dependency order'),
    ('20261105', 'S9:F01_B_r3'): ('05-7', '`E3/F01_B_r3/merged_graph.json` → `edges[9]`; UMLS in `edges[37]`', '“The embedding of the new case, existing cases, and experts is based on a medical ontology.”; `edges[37]` is Medical Ontology → Unified Medical Language System'),
    ('20261115', 'S3:supplement/Q11/mix'): ('15-1', '`E1/supplement_budget_Q11_supplementary_mix.json` → `result.llm_response.content` (1113 characters)', 'read in full; it opens with a refusal and says the context has no chunk, entity or reference for the patent'),
    ('20261115', 'S5:B1'): ('15-2', '`E2/ablation_B_r1.json` → `response.content`, from character 187', 'search “referencing US7991757B2”; the later “not tied to Claim 1 or Claim 27” says no matching claim was found'),
    ('20261115', 'S9:F01_A_r1'): ('15-3', '`E3/F01_A_r1/merged_graph.json` → `edges`', 'edge 7 (Diagnosis Assistance Method → Medical Ontology) only says “multidimensional representations of medical cases based on a medical ontology”; edges 33–39 neither. First chunk truncated (call 1)'),
    ('20261115', 'S9:F01_B_r1'): ('15-4', '`E3/F01_B_r1/merged_graph.json` → `edges[9]`; UMLS in `edges[36]`', '“The embedding of the new case, existing cases, and experts is based on a medical ontology.”'),
    ('20261115', 'S9:F01_B_r2'): ('15-5', '`E3/F01_B_r2/merged_graph.json` → `edges[7]`; UMLS in `edges[34]`', '“The embedding of the new medical case, existing cases, and experts is based on a medical ontology.”'),
    ('20261115', 'S9:F01_B_r3'): ('15-6', '`E3/F01_B_r3/merged_graph.json` → `edges[9]`; UMLS in `edges[43]`', 'as 15-5'),
    ('20261115', 'S13:F01_A_r2/naive'): ('15-7', '`E3/F01_A_r2/natural_naive.json` → `result.llm_response.content`', 'search “Explicit technical chain”: “claim 4 → claim 5 → claim 8”; in the original, claim 8 depends on claim 4, not on claim 5'),
    ('20261115', 'S13:F01_B_r2/naive'): ('15-8', '`E3/F01_B_r2/natural_naive.json` → `result.llm_response.content`', 'as 15-7 (“Claim 4 → Claim 5 → Claim 8”, also headed “Explicit technical chain”)'),
}


def j(p):
    return json.loads(Path(p).read_text()) if Path(p).exists() else {}


def yn(v):
    return 'yes' if v else 'no'


def main():
    md = ['# Human review record', '',
          'In the two reruns, 15 judgments had an uncertain rule or a rule value different from the original run (7 on 11-05, 8 on 11-15). '
          'They were reviewed first by Claude Code and then, item by item, by the author on **2026-11-15**. '
          'The review was done in Chinese; the author\'s original note is quoted below and in `human_review_<run>.json` (`note_zh`), '
          'next to an English translation by Claude Code (`note_en`). Generated by `tools/build_human_review.py` from the JSON files.', '']
    rows_all = []
    for label in LABELS:
        rules = {f"{r['rubric']}:{r['item']}": r['rule_value'] for r in j(OUT / f'scores_{label}.json').get('rows', [])}
        cc, hu = j(OUT / f'claude_review_{label}.json'), j(OUT / f'human_review_{label}.json')
        for k in hu:
            rows_all.append(rules.get(k) == cc.get(k, {}).get('value') == hu[k]['value'])
    md += [f"**Agreement**: the author's conclusion equals the Claude Code judgment and the rule value in {sum(rows_all)} of {len(rows_all)} items.", '',
           'Paths are relative to the repository root, with `E1` = `experiments/01_baseline_index_qa/results_rerun_<run>/results`, '
           '`E2` = `experiments/02_provenance_ablation_and_chunk_control/results_rerun_<run>/results`, '
           '`E3` = `experiments/03_chunk_boundary_full_pipeline/results_rerun_<run>/results`. `edges[n]` counts from 0.', '',
           '## Criteria in short', '',
           '| ID | What is judged | “Yes” when (from the [rubric](../SCORING_RUBRIC.md)) |', '|---|---|---|',
           '| S1 | experiment 01: the answer completes the core task | no refusal; names all publication numbers; names the claims of the question\'s evidence (cross-document: any claim within each patent\'s own paragraph) |',
           '| S3 | experiment 01: the answer **affirmatively** attributes the target facts to another patent | an affirmative misattribution such as “different patent family” |',
           '| S5 | experiment 02 ablation: the registration evidence is attributed to US7991757B2 | an affirmative statement (e.g. “referencing US7991757B2”) and no sentence denying it |',
           '| S9 | experiment 03: F01\'s target predicates reach the relation records of the merged graph | frozen criterion: the embedding of existing cases **and** experts is based on the medical ontology, and the ontology is based on UMLS; a relation about the new case only does not count ([`frozen_groups.json`](../../experiments/03_chunk_boundary_full_pipeline/conditions/frozen_groups.json) → F01 `researcher_predicate`) |',
           '| S13 | experiment 03 naive: states a claim dependency that contradicts the original | the answer says “A depends on B” where the original differs, or an arrow chain in a paragraph about dependencies contradicts the original |', '',
           'Dependencies in the original F01 (US9589231B2): claim 5 → 4, 6 → 5, 7 → 4, **8 → 4** (claim 8 does not depend on 5), 4 → 1.', '']
    for label, who in LABELS.items():
        rules = {f"{r['rubric']}:{r['item']}": r['rule_value'] for r in j(OUT / f'scores_{label}.json').get('rows', [])}
        cc, hu = j(OUT / f'claude_review_{label}.json'), j(OUT / f'human_review_{label}.json')
        md += [f'## {label[:4]}-{label[4:6]}-{label[6:]} (run {who})', '',
               '| # | Judgment | Rule | Claude Code | Evidence → location | What to look at | Human review (English translation) | Human review (original, Chinese) |',
               '|---|---|---|---|---|---|---|---|']
        for k in sorted(set(cc) | set(hu), key=lambda x: WHERE.get((label, x), ('99',))[0]):
            rid, loc, what = WHERE.get((label, k), ('?', '—', '—'))
            h = hu.get(k, {})
            md.append(f"| {rid} | {k.split(':', 1)[0]} `{k.split(':', 1)[1]}` | {yn(rules.get(k))} | {yn(cc.get(k, {}).get('value'))} | {loc} | {what} | "
                      f"{(yn(h['value']) + ' — ' + h.get('note_en', '')) if h else 'pending'} | {h.get('note_zh', '') if h else ''} |")
        md.append('')
    (OUT / 'HUMAN_REVIEW.md').write_text('\n'.join(md), encoding='utf-8')
    print('wrote docs/scoring/HUMAN_REVIEW.md')


if __name__ == '__main__':
    main()
